const SCENE = "smartciti-holodeck-sims";
const q = (s) => "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
const nums = (a) => a.map((x) => Number(x).toFixed(6)).join(', ');

async function main() {
  const dry = !!process.env.DRY && !['0', 'false', 'no'].includes(String(process.env.DRY).toLowerCase());  // DRY=0 is a real run
  const Settings = dry ? null : require('./settings.json');
  const conn = dry ? null : await require('mysql2/promise').createConnection({ ...Settings.SQL.config, multipleStatements: true });
  let calls = 0, longest = 0;
  const NAME_LIMIT = 48;  // Artemis 0.4.0 aborts on longer node names; the map service's name column is fixed-width too
  async function call(proc, parent, node) {
    calls++;
    longest = Math.max(longest, node.name.length);
    if (node.name.length > NAME_LIMIT) throw new Error(`node name over ${NAME_LIMIT} characters: ${node.name}`);
    const args = `'0.0.0.0', 1, ${parent}, ${q(node.name)}, 1, 0, 1, 0, 1, 0, '', ${q(node.ref)}, ` +
                 `${nums(node.pos)}, ${nums(node.rot)}, ${nums(node.scale)}, ${nums(node.bound)}`;
    const stmt = `CALL ${proc} (${args}, @nResult); SELECT @nResult AS nResult;`;
    if (dry) { if (calls <= 3) console.log(stmt); return calls; }
    const [res] = await conn.query(stmt);
    const ok = res[res.length - 1][0].nResult == 0;
    if (!ok) throw new Error(`${proc} failed for ${node.name}`);
    return res[0][0].twRMPObjectIx;
  }
  async function place(node, parentIx) {
    const ix = await call('set_RMPObject_RMPObject_Open', parentIx, node);
    for (const c of node.children) await place(c, ix);
  }
  const rootIx = await call('set_RMRoot_RMPObject_Open', 1, { ...TREE, name: TREE.name || SCENE });
  for (const c of TREE.children) await place(c, rootIx);
  console.log(`${dry ? 'DRY RUN: ' : ''}${SCENE}: ${calls} objects ${dry ? 'would be' : ''} created, longest name ${longest}/${NAME_LIMIT}`);
  if (conn) await conn.end();
}
main().catch((e) => { console.error(e.message); process.exit(1); });
